#include "tui/format.h"
#include "tui/terminal_guard.h"
#include "tui/view.h"
#include <cassert>
int main(){Telemetry t;t.particles=1000;t.frame=123;t.fps=58.9;t.sim_ms=12.4;t.stats.kinetic=12000;t.stats.potential=340000;t.contacts={4500,1200};t.grid_cells=262144;t.device_used_bytes=120*1024*1024;t.density.width=8;t.density.height=4;t.density.particles.assign(32,1);UiState s;Theme th=detect_theme(true,true);auto render=[](ftxui::Element e,int w,int h){auto x=ftxui::Screen::Create(ftxui::Dimension::Fixed(w),ftxui::Dimension::Fixed(h));ftxui::Render(x,e);return x.ToString();};auto n=render(render_dashboard(t,s,th),120,40);assert(n.find("TRON")!=std::string::npos);assert(n.find("FPS")!=std::string::npos);assert(n.find("PARTICLES")!=std::string::npos);t.paused=true;assert(render(render_dashboard(t,s,th),120,40).find("PAUSED")!=std::string::npos);t.stats.firstNonFinite=123;assert(render(render_dashboard(t,s,th),120,40).find("NaN")!=std::string::npos);s.field_width=60;assert(render(render_dashboard(t,s,th),60,20).find("Terminal too small")!=std::string::npos);assert(render(render_help(th),100,30).find("Space")!=std::string::npos);assert(format_count(1000000)=="1.00M");assert(format_count(10000)=="10.0k");assert(format_bytes(120ull*1024*1024)=="120 MiB");assert(terminal_restore_sequence().find("\x1b[?25h")!=std::string::npos);}
